'use strict';

/**
 * Seeds Strapi with the Dragon Capital content.
 *
 *   npm run seed            # create content if it does not exist yet
 *   npm run seed -- --force # overwrite existing content
 *
 * Global + Homepage come from seed-data.js. Sites, pages, funds, articles, fund documents
 * and the document taxonomy come from scripts/content/ (generated by convert-crawl.py from
 * the crawl of the live site), with media under ../seed-assets/content.
 *
 * Also: makes Vietnamese the default locale, opens read access for the public
 * role, creates a write-only API token for the contact form and a webhook that
 * revalidates the Next.js cache. Token + webhook secret go to ../frontend/.env.local.
 */
const fs = require('fs');
const zlib = require('zlib');
const path = require('path');
const crypto = require('crypto');
const { createStrapi, compileStrapi } = require('@strapi/strapi');
const data = require('./seed-data');

const LOCALE = 'vi';
const LOCALES = ['vi', 'en'];
const CONTENT_DIR = path.join(__dirname, 'content');
const DOC_BATCH = 500;
const ASSET_DIR = path.join(__dirname, '..', '..', 'seed-assets');
const CMS_ENV = path.join(__dirname, '..', '.env');
const FRONTEND_ENV = path.join(__dirname, '..', '..', 'frontend', '.env.local');
const FRONTEND_URL = process.env.FRONTEND_URL || 'http://localhost:3000';
const TOKEN_NAME = 'nextjs-contact-form';
const WEBHOOK_NAME = 'nextjs-revalidate';
const force = process.argv.includes('--force');

function ensureCmsEnv() {
  if (fs.existsSync(CMS_ENV)) return;
  const secret = () => crypto.randomBytes(16).toString('hex');
  const defaults = {
    HOST: '0.0.0.0',
    PORT: '1337',
    APP_KEYS: `${secret()},${secret()}`,
    API_TOKEN_SALT: secret(),
    ADMIN_JWT_SECRET: secret(),
    TRANSFER_TOKEN_SALT: secret(),
    JWT_SECRET: secret(),
    ENCRYPTION_KEY: secret(),
  };
  const content =
    Object.entries(defaults)
      .map(([k, v]) => `${k}=${v}`)
      .join('\n') + '\n';
  fs.writeFileSync(CMS_ENV, content);
  for (const [k, v] of Object.entries(defaults)) {
    if (!process.env[k]) process.env[k] = v;
  }
  console.log(`  wrote ${path.relative(process.cwd(), CMS_ENV)}`);
}

async function ensureLocale(strapi) {
  const locales = strapi.plugin('i18n').service('locales');
  if (!(await locales.findByCode(LOCALE))) {
    await locales.create({ code: LOCALE, name: 'Vietnamese (vi)' });
  }
  if (!(await locales.findByCode('en'))) {
    await locales.create({ code: 'en', name: 'English (en)' });
  }
  await locales.setDefaultLocale({ code: LOCALE });
}

async function grantPublic(strapi, actions) {
  const role = await strapi.db.query('plugin::users-permissions.role').findOne({ where: { type: 'public' } });
  for (const action of actions) {
    const exists = await strapi.db
      .query('plugin::users-permissions.permission')
      .findOne({ where: { action, role: role.id } });
    if (!exists) {
      await strapi.db.query('plugin::users-permissions.permission').create({ data: { action, role: role.id } });
    }
  }
}

const MIME = {
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.webp': 'image/webp',
  '.gif': 'image/gif',
  '.json': 'application/json',
  '.pdf': 'application/pdf',
};

async function uploadFile(strapi, { file, mime, alt, name = file }) {
  const existing = await strapi.db.query('plugin::upload.file').findOne({ where: { name } });
  if (existing) return existing;
  const filepath = path.join(ASSET_DIR, file);
  const [uploaded] = await strapi
    .plugin('upload')
    .service('upload')
    .upload({
      files: { filepath, originalFilename: name, mimetype: mime, size: fs.statSync(filepath).size },
      data: { fileInfo: { name, alternativeText: alt, caption: alt } },
    });
  return uploaded;
}

// ---- generated content (scripts/content) -------------------------------------------

function readContent(name) {
  return JSON.parse(fs.readFileSync(path.join(CONTENT_DIR, name), 'utf8'));
}

/** Uploads `{ $media: 'content/…', alt }` references once per path and remembers the upload. */
function createMediaResolver(strapi) {
  const cache = new Map();
  const upload = async (file, alt) => {
    if (!cache.has(file)) {
      const mime = MIME[path.extname(file).toLowerCase()];
      if (!mime) throw new Error(`Unknown media type: ${file}`);
      // Upload names can't contain '/', so content/news/x.jpg is stored as news-x.jpg
      const name = file.replace(/^content\//, '').replace(/\//g, '-');
      cache.set(file, uploadFile(strapi, { file, mime, name, alt: alt || path.basename(file) }));
    }
    return cache.get(file);
  };
  const MD_MEDIA = /media:(content\/[^\s)"']+)/g;
  const resolve = async value => {
    if (Array.isArray(value)) return Promise.all(value.map(resolve));
    if (typeof value === 'string') {
      if (!value.includes('media:content/')) return value;
      let out = value;
      for (const [, file] of value.matchAll(MD_MEDIA)) {
        const uploaded = await upload(file);
        out = out.split(`media:${file}`).join(uploaded.url);
      }
      return out;
    }
    if (value && typeof value === 'object') {
      if (typeof value.$media === 'string') return (await upload(value.$media, value.alt)).id;
      const out = {};
      for (const [k, v] of Object.entries(value)) out[k] = await resolve(v);
      return out;
    }
    return value;
  };
  return resolve;
}

/**
 * Creates or updates one localized document: the vi version first, then the en localization
 * of the same document, publishing both. Entries look like { ...sharedFields, locales: { vi, en } }.
 */
async function upsertLocalized(strapi, uid, filters, entry, resolveMedia) {
  const docs = strapi.documents(uid);
  const existing = await docs.findFirst({ filters, locale: LOCALE });
  if (existing && !force) return 'skipped';
  const { locales, ...shared } = entry;
  let documentId = existing && existing.documentId;
  for (const locale of LOCALES) {
    if (!locales[locale]) continue;
    const data = await resolveMedia({ ...shared, ...locales[locale] });
    if (documentId) {
      await docs.update({ documentId, locale, data });
    } else {
      ({ documentId } = await docs.create({ locale, data }));
    }
    await docs.publish({ documentId, locale });
  }
  return existing ? 'updated' : 'created';
}

async function seedCollection(strapi, uid, entries, keyOf, resolveMedia) {
  const counts = { created: 0, updated: 0, skipped: 0 };
  for (const entry of entries) {
    try {
      counts[await upsertLocalized(strapi, uid, keyOf(entry), entry, resolveMedia)] += 1;
    } catch (err) {
      const detail = err.details && err.details.errors ? JSON.stringify(err.details.errors) : '';
      throw new Error(`${uid} ${JSON.stringify(keyOf(entry))}: ${err.message} ${detail}`);
    }
  }
  console.log(`  ${uid}: ${counts.created} created, ${counts.updated} updated, ${counts.skipped} skipped`);
}

async function seedLocalizedSingleType(strapi, uid, entry, resolveMedia) {
  const docs = strapi.documents(uid);
  const existing = await docs.findFirst({ locale: LOCALE });
  if (existing && !force) {
    console.log(`  ${uid}: already has content, skipped (use --force to overwrite)`);
    return;
  }
  let documentId = existing && existing.documentId;
  for (const locale of LOCALES) {
    const data = await resolveMedia(entry.locales[locale]);
    if (documentId) await docs.update({ documentId, locale, data });
    else ({ documentId } = await docs.create({ locale, data }));
    await docs.publish({ documentId, locale });
  }
  console.log(`  ${uid}: seeded`);
}

/** ~48k rows: bulk insert straight into the table (no draft/publish, not localized). */
async function seedFundDocuments(strapi) {
  const uid = 'api::fund-document.fund-document';
  const query = strapi.db.query(uid);
  const existing = await query.count();
  if (existing && !force) {
    console.log(`  ${uid}: ${existing} rows already, skipped (use --force to overwrite)`);
    return;
  }
  if (existing) await query.deleteMany({});
  const lines = zlib
    .gunzipSync(fs.readFileSync(path.join(CONTENT_DIR, 'fund-documents.jsonl.gz')))
    .toString('utf8')
    .split('\n')
    .filter(Boolean);
  const now = new Date();
  let batch = [];
  let total = 0;
  const flush = async () => {
    if (!batch.length) return;
    await query.createMany({ data: batch });
    total += batch.length;
    batch = [];
  };
  for (const line of lines) {
    const doc = JSON.parse(line);
    batch.push({ ...doc, documentId: crypto.randomUUID(), createdAt: now, updatedAt: now, publishedAt: now });
    if (batch.length >= DOC_BATCH) await flush();
  }
  await flush();
  console.log(`  ${uid}: ${total} rows inserted`);
}

async function seedGeneratedContent(strapi) {
  if (!fs.existsSync(CONTENT_DIR)) {
    console.log('  scripts/content not found, skipped (run convert-crawl.py first)');
    return;
  }
  const resolveMedia = createMediaResolver(strapi);
  await seedCollection(strapi, 'api::site.site', readContent('sites.json'), e => ({ key: e.key }), resolveMedia);
  await seedCollection(strapi, 'api::article.article', readContent('articles.json'), e => ({ slug: e.slug }), resolveMedia);
  await seedCollection(
    strapi,
    'api::fund.fund',
    readContent('funds.json'),
    e => ({ slug: e.slug, audience: e.audience }),
    resolveMedia
  );
  await seedCollection(strapi, 'api::page.page', readContent('pages.json'), e => ({ path: e.path }), resolveMedia);
  await seedLocalizedSingleType(
    strapi,
    'api::document-taxonomy.document-taxonomy',
    readContent('document-taxonomy.json'),
    resolveMedia
  );
  await seedFundDocuments(strapi);
}

async function upsertSingleType(strapi, uid, content) {
  const docs = strapi.documents(uid);
  const existing = await docs.findFirst({ locale: LOCALE });
  if (existing && !force) {
    console.log(`  ${uid}: already has content, skipped (use --force to overwrite)`);
    return;
  }
  if (existing) {
    await docs.update({ documentId: existing.documentId, locale: LOCALE, data: content });
    await docs.publish({ documentId: existing.documentId, locale: LOCALE });
  } else {
    await docs.create({ locale: LOCALE, data: content, status: 'published' });
  }
  console.log(`  ${uid}: seeded`);
}

function readFrontendEnv() {
  if (!fs.existsSync(FRONTEND_ENV)) return {};
  return Object.fromEntries(
    fs.readFileSync(FRONTEND_ENV, 'utf8').split('\n').filter(l => l.includes('=')).map(l => [l.slice(0, l.indexOf('=')), l.slice(l.indexOf('=') + 1)])
  );
}

/** Reuses the token already in frontend/.env.local when it still matches, so a running Next.js keeps working. */
async function ensureApiToken(strapi, current) {
  const tokens = strapi.service('admin::api-token');
  const existing = await tokens.getByName(TOKEN_NAME);
  if (existing && current) {
    const row = await strapi.db.query('admin::api-token').findOne({ where: { id: existing.id }, select: ['accessKey'] });
    if (row?.accessKey === tokens.hash(current)) return current;
  }
  if (existing) {
    const { accessKey } = await tokens.regenerate(existing.id);
    return accessKey;
  }
  const { accessKey } = await tokens.create({
    name: TOKEN_NAME,
    description: 'Lets the Next.js server create contact submissions. Nothing else.',
    type: 'custom',
    lifespan: null,
    permissions: ['api::contact-submission.contact-submission.create'],
  });
  return accessKey;
}

async function ensureWebhook(strapi, secret) {
  const store = strapi.get('webhookStore');
  const hooks = await store.findWebhooks();
  const def = {
    name: WEBHOOK_NAME,
    url: `${FRONTEND_URL}/api/revalidate`,
    headers: { Authorization: `Bearer ${secret}` },
    events: ['entry.create', 'entry.update', 'entry.delete', 'entry.publish', 'entry.unpublish', 'media.update'],
    isEnabled: true,
  };
  const existing = hooks.find(h => h.name === WEBHOOK_NAME);
  if (existing) await store.updateWebhook(existing.id, def);
  else await store.createWebhook(def);
}

function writeFrontendEnv(values) {
  let current = fs.existsSync(FRONTEND_ENV) ? fs.readFileSync(FRONTEND_ENV, 'utf8') : '';
  for (const [key, value] of Object.entries(values)) {
    const line = `${key}=${value}`;
    const re = new RegExp(`^${key}=.*$`, 'm');
    current = re.test(current) ? current.replace(re, line) : `${current.trimEnd()}\n${line}\n`.trimStart();
  }
  fs.mkdirSync(path.dirname(FRONTEND_ENV), { recursive: true });
  fs.writeFileSync(FRONTEND_ENV, current.endsWith('\n') ? current : `${current}\n`);
}

async function main() {
  ensureCmsEnv();
  const app = await createStrapi(await compileStrapi()).load();
  app.log.level = 'error';
  try {
    console.log('Locale…');
    await ensureLocale(app);

    console.log('Public permissions…');
    await grantPublic(app, [
      'api::global.global.find',
      'api::homepage.homepage.find',
      'api::document-taxonomy.document-taxonomy.find',
      ...['site', 'page', 'article', 'fund', 'fund-document'].flatMap(t => [
        `api::${t}.${t}.find`,
        `api::${t}.${t}.findOne`,
      ]),
    ]);

    console.log('Media…');
    const media = {};
    for (const [key, def] of Object.entries(data.files)) media[key] = await uploadFile(app, def);

    console.log('Content…');
    await upsertSingleType(app, 'api::global.global', {
      ...data.global,
      logo: media.logo.id,
      favicon: media.favicon.id,
    });
    await upsertSingleType(app, 'api::homepage.homepage', {
      ...data.homepage,
      heroAnimation: media.heroAnimation.id,
      aboutImage: media.aboutImage.id,
      contactImage: media.contactImage.id,
    });

    console.log('Sites, pages, funds, articles, documents…');
    const started = Date.now();
    await seedGeneratedContent(app);
    console.log(`  done in ${((Date.now() - started) / 1000).toFixed(1)} s`);

    console.log('API token + revalidation webhook…');
    const env = readFrontendEnv();
    const token = await ensureApiToken(app, env.STRAPI_WRITE_TOKEN);
    const secret = env.REVALIDATE_SECRET || crypto.randomBytes(24).toString('hex');
    await ensureWebhook(app, secret);
    writeFrontendEnv({
      STRAPI_URL: `http://localhost:${app.config.get('server.port', 1337)}`,
      STRAPI_WRITE_TOKEN: token,
      REVALIDATE_SECRET: secret,
    });
    console.log(`  wrote ${path.relative(process.cwd(), FRONTEND_ENV)}`);
    console.log('Done.');
  } finally {
    await app.destroy();
  }
}

main().catch(err => {
  console.error(err);
  process.exit(1);
});
